async function loadUser(id: string): Promise<any> {
  const userRes = await fetch('/api/users/' + id);
  if (!userRes.ok) {
    throw new Error('bad status ' + userRes.status);
  }
  const u = await userRes.json();
  const orgRes = await fetch('/api/orgs/' + u.orgId);
  if (!orgRes.ok) {
    throw new Error('bad status ' + orgRes.status);
  }
  u.org = await orgRes.json();
  return u;
}

async function loadUsers(ids: string[]): Promise<any[]> {
  const out: any[] = [];
  for (let i = 0; i < ids.length; i++) {
    out[i] = await loadUser(ids[i]);
  }
  return out;
}

export { loadUser, loadUsers };
